// Generated by `regia package --platform android`. Regenerated on every build; do not edit.
// The native code is prebuilt by `cargo ndk` into src/main/jniLibs; Gradle only packages it.

plugins {
    id("com.android.application")
}

android {
    namespace = "{{id}}"
    compileSdk = {{target_sdk}}
{{ndk_path}}{{signing_config}}
    defaultConfig {
        applicationId = "{{id}}"
        minSdk = {{min_sdk}}
        targetSdk = {{target_sdk}}
        versionCode = {{version_code}}
        versionName = "{{version_name}}"
        ndk {
            abiFilters += listOf({{abi_filters}})
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    // Paks are read straight out of the APK, so they must be stored uncompressed.
    androidResources {
        noCompress += "fpak"
    }
{{asset_packs}}}

dependencies {
    // Must match the GameActivity version the `android-activity` crate compiles its C glue against
    // (android-activity 0.6.1 -> GameActivity 4.4.0). No prefab: the glue is built into libmain.so.
    implementation("androidx.games:games-activity:{{games_activity_version}}")
    implementation("androidx.appcompat:appcompat:{{appcompat_version}}")
    // appcompat pulls kotlin-stdlib {{kotlin_version}} and (via kotlinx-coroutines) the old split
    // kotlin-stdlib-jdk7/jdk8 1.6.x, whose classes now live in kotlin-stdlib: align them all, or
    // checkDebugDuplicateClasses fails. (Projects with the Kotlin plugin get this alignment for free.)
    implementation(platform("org.jetbrains.kotlin:kotlin-bom:{{kotlin_version}}"))
{{asset_delivery_dependency}}}
